import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import * as I from 'lucide-react';
import './styles.css';
import './workflow.css';
import './conversation.css';
import { firebaseEnabled } from './config/firebase';
import { listConversations, saveConversation, updateConversation } from './services/firestore';
import VoiceAiPage from './VoiceAiPage';
import CallbackSystemControl from './CallbackSystemControl';
import AuthPage from './AuthPages';

type Page = 'home'|'workflows'|'simulator'|'conversations'|'businesses'|'customers'|'followups'|'calendar'|'analytics'|'voice'|'settings';
type Conversation = { name:string; type:string; time:string; status:string; priority:'URGENT'|'NORMAL'; initials:string; color:string; text:string };

const conversations: Conversation[] = [
 {name:'Sarah Johnson',type:'New appointment request',time:'2 min ago',status:'In progress',priority:'URGENT',initials:'SJ',color:'#d9f3e5',text:'I need to see Dr. Rao tomorrow morning.'},
 {name:'Rahul Mehta',type:'Cake order inquiry',time:'18 min ago',status:'Booked',priority:'NORMAL',initials:'RM',color:'#eee6ff',text:'Can I get a custom chocolate cake for Saturday?'},
 {name:'Priya Nair',type:'Follow-up call',time:'1 hr ago',status:'Contacted',priority:'NORMAL',initials:'PN',color:'#fff0d8',text:'Calling back about the delivery options.'},
 {name:'David Chen',type:'Appointment reschedule',time:'3 hrs ago',status:'Closed',priority:'NORMAL',initials:'DC',color:'#dceeff',text:'Could we move my appointment to next week?'}
];
const nav: {id:Page; label:string; icon:React.ElementType}[] = [
 {id:'home',label:'Overview',icon:I.LayoutDashboard},{id:'workflows',label:'Workflows',icon:I.Workflow},{id:'simulator',label:'AI Simulator',icon:I.Sparkles},{id:'conversations',label:'Conversations',icon:I.MessageSquare},{id:'customers',label:'Customers',icon:I.Users},{id:'followups',label:'Follow-ups',icon:I.ListChecks},{id:'calendar',label:'Calendar',icon:I.CalendarDays},{id:'analytics',label:'Analytics',icon:I.BarChart3},{id:'voice',label:'Voice AI',icon:I.PhoneCall},{id:'settings',label:'Settings',icon:I.Settings}
];

function App(){
 const [page,setPage]=useState<Page>('home'); const [more,setMore]=useState(false); const [query,setQuery]=useState('');
 const path=window.location.pathname; const authMode=path==='/forgot-password'?'forgot':path.slice(1) as 'login'|'signup'|'onboarding'; if(path==='/login'||path==='/signup'||path==='/forgot-password'||path==='/onboarding') return <AuthPage mode={authMode}/>;
 const current=nav.find(n=>n.id===page) ?? nav[0];
 const go=(p:Page)=>{setPage(p);setMore(false)};
 return <div className="app-shell">
   <CallbackSystemControl page={page}/>
   <aside className="sidebar"><div className="brand"><div className="brand-mark"><I.Waves size={20}/></div><span>voxly<span className="brand-dot">.</span></span></div><div className="workspace"><div className="avatar">MS</div><div><b>Mangalore Smile Clinic</b><small>Workspace</small></div><I.ChevronsUpDown size={15}/></div><nav>{nav.map(n=><button key={n.id} className={page===n.id?'nav-item active':'nav-item'} onClick={()=>go(n.id)}><n.icon size={18}/><span>{n.label}</span>{n.id==='conversations'&&<em>4</em>}</button>)}</nav><div className="upgrade"><div className="upgrade-icon"><I.Zap size={16}/></div><b>Unlock more with Pro</b><p>Unlimited workflows and calls.</p><button>Upgrade plan <I.ArrowUpRight size={14}/></button></div><div className="profile"><div className="avatar purple">AK</div><div><b>Arjun Kumar</b><small>Admin</small></div><I.MoreHorizontal size={17}/></div></aside>
   <main className="main"><header className="topbar"><div className="mobile-brand"><div className="brand-mark"><I.Waves size={18}/></div><span>voxly<span className="brand-dot">.</span></span></div><div className="crumb"><span>Workspace</span><I.ChevronRight size={14}/><b>{current.label}</b></div><div className="top-actions"><button className="icon-btn"><I.HelpCircle size={18}/></button><button className="icon-btn"><I.Bell size={18}/><i></i></button><div className="avatar purple">AK</div></div></header><div className="page-wrap">{page==='home'?<Dashboard go={go}/>:page==='workflows'?<Workflows go={go}/>:page==='simulator'?<WorkflowSimulator/>:page==='conversations'?<Conversations query={query} setQuery={setQuery}/>:page==='customers'?<Customers/>:page==='followups'?<Followups/>:page==='calendar'?<CalendarPage/>:page==='analytics'?<Analytics/>:page==='voice'?<VoiceAiPage/>:page==='settings'?<Settings/>:<Businesses/>}</div></main>
   <div className="mobile-nav">{nav.slice(0,4).map(n=><button key={n.id} onClick={()=>go(n.id)} className={page===n.id?'selected':''}><n.icon size={19}/><span>{n.id==='home'?'Home':n.label.split(' ')[0]}</span></button>)}<button onClick={()=>setMore(true)} className={more?'selected':''}><I.Menu size={19}/><span>More</span></button></div>
   {more&&<div className="sheet-backdrop" onClick={()=>setMore(false)}><div className="bottom-sheet" onClick={e=>e.stopPropagation()}><div className="sheet-handle"/><h3>More in Voxly</h3><div className="sheet-grid">{nav.slice(4).map(n=><button key={n.id} onClick={()=>go(n.id)}><n.icon size={19}/><span>{n.label}</span></button>)}</div></div></div>}
 </div>
}

function PageTitle({eyebrow,title,description,action}:{eyebrow?:string;title:string;description?:string;action?:React.ReactNode}){return <div className="page-title"><div><div className="eyebrow">{eyebrow||'WORKSPACE'}</div><h1>{title}</h1>{description&&<p>{description}</p>}</div>{action}</div>}
function Stat({icon,color,label,value,delta}:{icon:React.ReactNode;color:string;label:string;value:string;delta:string}){return <div className="stat-card"><div className="stat-top"><div className="stat-icon" style={{background:color}}>{icon}</div><span className="delta">{delta}</span></div><div className="stat-value">{value}</div><div className="stat-label">{label}</div></div>}
function Button({children,secondary=false,onClick}:{children:React.ReactNode;secondary?:boolean;onClick?:()=>void}){return <button onClick={onClick} className={secondary?'btn secondary':'btn'}>{children}</button>}
function Dashboard({go}:{go:(p:Page)=>void}){return <><PageTitle eyebrow="TUESDAY, SEPTEMBER 8, 2026" title="Good morning, Arjun" description="Here’s what’s happening across your assistant today." action={<Button onClick={()=>go('workflows')}><I.Plus size={17}/> New workflow</Button>}/><div className="stats"><Stat icon={<I.PhoneMissed size={19}/>} color="#ffe4e0" label="Missed calls" value="12" delta="↓ 18%"/><Stat icon={<I.MessageCircle size={19}/>} color="#dff5e9" label="Active conversations" value="08" delta="↑ 24%"/><Stat icon={<I.Clock3 size={19}/>} color="#fff0ce" label="Pending follow-ups" value="06" delta="2 due today"/><Stat icon={<I.AlertCircle size={19}/>} color="#eee5ff" label="Urgent requests" value="03" delta="Needs attention"/></div><div className="content-grid"><section className="panel conversations-panel"><div className="panel-head"><div><h2>Recent conversations</h2><p>Latest activity from your AI assistant</p></div><button className="text-btn" onClick={()=>go('conversations')}>View all <I.ArrowRight size={15}/></button></div>{conversations.slice(0,3).map(c=><ConversationRow key={c.name} c={c}/>)}</section><section className="panel appointments"><div className="panel-head"><div><h2>Today’s appointments</h2><p>Tuesday, September 8</p></div><button className="icon-btn"><I.MoreHorizontal size={18}/></button></div><div className="date-strip"><b>08</b><span>Sep<br/><small>Today</small></span></div>{[['09:30 AM','Sarah Johnson','Dental consultation','green'],['11:00 AM','Rahul Mehta','Follow-up visit','purple'],['02:30 PM','Priya Nair','New patient check-in','orange']].map(x=><div className="appointment" key={x[0]}><time>{x[0]}</time><div className={'apt-dot '+x[3]}></div><div><b>{x[1]}</b><small>{x[2]}</small></div></div>)}</section></div><section className="panel insight"><div className="insight-art"><div className="sparkle">✦</div><div className="orb"></div></div><div><span className="eyebrow">WEEKLY INSIGHT</span><h2>Your assistant is getting smarter.</h2><p>Voxly handled 84% of conversations without human help this week — up 12% from last week.</p></div><Button secondary onClick={()=>go('analytics')}>View analytics <I.ArrowRight size={15}/></Button></section></>}
function ConversationRow({c}:{c:Conversation}){return <div className="conversation-row"><div className="avatar" style={{background:c.color}}>{c.initials}</div><div className="conversation-main"><b>{c.name}</b><span>{c.type}</span><small>{c.text}</small></div><div className="conversation-meta"><span className={'priority '+c.priority.toLowerCase()}>{c.priority}</span><small>{c.time}</small></div><I.ChevronRight className="row-chevron" size={16}/></div>}
function Workflows({go}:{go:(p:Page)=>void}){const [published,setPublished]=useState(false); return <><PageTitle eyebrow="AUTOMATIONS" title="Workflows" description="Design the conversations your AI assistant handles for you." action={<Button onClick={()=>go('simulator')}><I.Plus size={17}/> Create workflow</Button>}/><div className="workflow-banner"><div className="workflow-symbol"><I.Workflow size={23}/></div><div><b>Build your first intelligent workflow</b><p>Collect details, make decisions, and take action automatically.</p></div><Button onClick={()=>setPublished(!published)}>{published?'Workflow published':'Start building'} <I.ArrowRight size={15}/></Button></div><div className="workflow-cards"><WorkflowCard icon="✦" color="purple" title="Clinic Appointment Booking" subtitle="Mangalore Smile Clinic" active={published||true} steps="5 steps"/><WorkflowCard icon="◒" color="orange" title="Custom Cake Order" subtitle="Sweet Crumbs Cake Shop" active={false} steps="7 steps"/><div className="add-card" onClick={()=>go('simulator')}><div><I.Plus size={22}/></div><b>Create a new workflow</b><span>Start from scratch or use a template</span></div></div><div className="panel table-panel"><div className="panel-head"><div><h2>Workflow performance</h2><p>How your automations are performing</p></div><button className="filter-btn">Last 30 days <I.ChevronDown size={14}/></button></div><div className="table"><div className="tr th"><span>Workflow</span><span>Conversations</span><span>Completion</span><span>Status</span></div>{[['Clinic Appointment Booking','128','86%','Live'],['Custom Cake Order','64','74%','Draft']].map(r=><div className="tr" key={r[0]}><span><b>{r[0]}</b></span><span>{r[1]}</span><span>{r[2]}</span><span><i className={r[3]==='Live'?'live-dot':'draft-dot'}></i>{r[3]}</span></div>)}</div></div></>}
function WorkflowCard({icon,color,title,subtitle,active,steps}:{icon:string;color:string;title:string;subtitle:string;active:boolean;steps:string}){return <div className="workflow-card"><div className={'workflow-icon '+color}>{icon}</div><div className="workflow-card-title"><b>{title}</b><span>{subtitle}</span></div><div className="workflow-status"><i className={active?'live-dot':'draft-dot'}></i>{active?'Live':'Draft'}</div><div className="workflow-bottom"><span><I.GitBranch size={14}/>{steps}</span><span><I.MessageSquare size={14}/> 128 conversations</span><button className="icon-btn"><I.MoreHorizontal size={18}/></button></div></div>}
function Simulator(){const [messages,setMessages]=useState([{from:'ai',text:'Hi! I’m Maya, the AI assistant for Mangalore Smile Clinic. How can I help you today?'},{from:'user',text:'I’d like to book an appointment for tomorrow.'},{from:'ai',text:'Absolutely. I can help with that. May I have your name and preferred specialty?'}]);const [input,setInput]=useState(''); const send=()=>{if(!input.trim())return;const next=[...messages,{from:'user' as const,text:input},{from:'ai' as const,text:'Thanks — I’ve captured that. What time works best for you?'}];setMessages(next);setInput('');if(firebaseEnabled){void saveConversation({workflowId:'clinic-appointment',transcript:next,extractedFields:{preferred_date:'tomorrow'},priority:'NORMAL',status:'in_progress'}).catch(console.error)}};return <><PageTitle eyebrow="TEST YOUR ASSISTANT" title="AI Simulator" description="Run a conversation and see how Voxly thinks in real time." action={<div className="language-toggle"><button className="selected">English</button><button>हिन्दी</button></div>}/><div className="simulator-layout"><section className="panel chat-panel"><div className="chat-head"><div className="assistant-avatar"><I.Waves size={20}/></div><div><b>Maya · Clinic Booking</b><span><i className="live-dot"></i> Ready to test</span></div><button className="icon-btn"><I.RotateCcw size={17}/></button></div><div className="chat-messages">{messages.map((m,i)=><div className={'bubble-wrap '+m.from} key={i}><span className="bubble-label">{m.from==='ai'?'Maya':'You'}</span><div className="bubble">{m.text}</div>{m.from==='ai'&&<small>just now</small>}</div>)}</div><div className="chat-input"><input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="Type a message to test your assistant..."/><button onClick={send}><I.ArrowUp size={18}/></button></div></section><aside className="panel inspector"><div className="panel-head"><div><h2>Live inspector</h2><p>Structured conversation state</p></div><span className="live-pill"><i className="live-dot"></i> Live</span></div><InspectorRow label="Intent" value="book_appointment"/><InspectorRow label="Priority" value="NORMAL" green/><div className="inspect-section"><span>COLLECTED FIELDS</span><div className="field-row"><b>preferred_date</b><span className="filled">Tomorrow</span></div><div className="field-row"><b>patient_name</b><span className="missing">Missing</span></div><div className="field-row"><b>specialty</b><span className="missing">Missing</span></div></div><div className="inspect-section"><span>NEXT ACTION</span><div className="next-action"><I.MessageCircle size={16}/><b>Ask for patient name</b></div></div></aside></div></>}
function detectCalendarDate(text:string){const value=text.toLowerCase();return value.match(/\b(?:\d{1,4}[/-]\d{1,2}[/-]\d{1,4}|\d{1,2}\s+(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)(?:\s+\d{2,4})?)\b/)?.[0]||value.match(/today|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday/)?.[0]}
function WorkflowSimulator(){
 const [workflowId,setWorkflowId]=useState('auto'); const [workflowFields,setWorkflowFields]=useState<string[]>([]); const [messages,setMessages]=useState<{from:'ai'|'user';text:string}[]>([{from:'ai',text:'Hi! I can help with a clinic appointment or a custom cake order. What would you like to arrange?'}]);
 const [input,setInput]=useState(''); const [busy,setBusy]=useState(false); const [conversationId,setConversationId]=useState<string|undefined>(); const [fields,setFields]=useState<Record<string,unknown>>({}); const [intent,setIntent]=useState('general_inquiry'); const [action,setAction]=useState('choose_workflow'); const [priority,setPriority]=useState<'URGENT'|'NORMAL'>('NORMAL'); const [conversationState,setConversationState]=useState('collecting'); const [currentFieldKey,setCurrentFieldKey]=useState<string|null>(null); const [workflowName,setWorkflowName]=useState('Auto-detect workflow');
 const meta=workflowId==='cake-order'?{name:'Custom Cake Order',assistant:'Maya',business:'Sweet Crumbs Cake Shop',fields:['customer_name','phone_number','cake_type','cake_flavour','cake_weight','required_date','custom_message','delivery_method','delivery_address','budget']}:{name:'Clinic Appointment Booking',assistant:'Maya',business:'Mangalore Smile Clinic',fields:['patient_name','phone_number','doctor_specialty','appointment_date','appointment_time','reason_for_visit']};
 const labels:Record<string,string>={patient_name:'Patient name',customer_name:'Customer name',phone_number:'Phone number',preferred_date:'Preferred date',appointment_date:'Appointment date',required_date:'Required date',specialty:'Doctor / specialty',doctor_specialty:'Doctor / specialty',preferred_time:'Preferred time',appointment_time:'Appointment time',flavor:'Cake flavor',cake_flavour:'Cake flavour',weight:'Cake weight',cake_weight:'Cake weight',fulfillment:'Delivery or pickup',delivery_method:'Delivery or pickup',cake_type:'Cake type',custom_message:'Cake message',delivery_address:'Delivery address',reason_for_visit:'Reason for visit',budget:'Budget'};
 const reset=(selected='auto')=>{setWorkflowId(selected);setWorkflowFields([]);setWorkflowName(selected==='cake-order'?'Cake Shop - Place Cake Order':selected==='clinic-appointment'?'Clinic - Book Appointment':'Auto-detect workflow');setMessages([{from:'ai',text:selected==='cake-order'?'Hi! I’m Coco from Sweet Crumbs Cake Shop. What kind of custom cake would you like?':selected==='clinic-appointment'?'Hi! I’m Maya from Mangalore Smile Clinic. How can I help with your appointment?':'Hi! I can help with a clinic appointment or a custom cake order. What would you like to arrange?'}]);setInput('');setFields({});setIntent('general_inquiry');setAction(selected==='auto'?'choose_workflow':'ask_for_field');setPriority('NORMAL');setConversationId(undefined);setConversationState('collecting');setCurrentFieldKey(null)};
 const send=async()=>{const text=input.trim();if(!text||busy)return;const userMessage={from:'user' as const,text};const history=[...messages,userMessage];setMessages(history);setInput('');setBusy(true);let reply='Tell me a little more so I can choose the right workflow.';let nextFields=fields;let nextIntent=intent;let nextAction=action;let nextPriority=priority;let nextConversationId=conversationId;let nextWorkflowId=workflowId;let nextWorkflowFields=workflowFields;
  try{const response=await fetch(`${import.meta.env.VITE_API_BASE_URL||'http://127.0.0.1:8000'}/api/ai/chat`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,conversation_id:conversationId,workflow_id:workflowId,language:'en',fields,current_field_key:currentFieldKey,state:conversationState,history})});if(!response.ok)throw new Error('AI API request failed');const data=await response.json();reply=data.assistant_reply;nextFields=data.extracted_fields||{};nextIntent=data.intent||'general_inquiry';nextAction=data.action_required||'ask_for_field';nextConversationId=data.conversation_id;nextWorkflowId=data.workflow_id||workflowId;nextWorkflowFields=(data.workflow_fields||[]).map((field:{key:string})=>field.key||field);nextPriority=data.priority||((nextFields.appointment_date==='today'||nextFields.appointment_date==='tomorrow'||nextFields.required_date==='today'||nextFields.required_date==='tomorrow')?'URGENT':'NORMAL');setWorkflowName(data.workflow_name||workflowName);setConversationState(data.state||'collecting');setCurrentFieldKey(data.current_field_key||null)}catch(error){console.error(error);const lower=text.toLowerCase();const cakeDetected=/cake|flavor|flavour|icing|bakery|delivery|pickup|kg/.test(lower);nextWorkflowId=workflowId==='auto'?(cakeDetected?'cake-order':'clinic-appointment'):workflowId;const fallbackFields=nextWorkflowId==='cake-order'?['customer_name','phone_number','cake_type','cake_flavour','cake_weight','required_date','delivery_method','delivery_address']:['patient_name','phone_number','doctor_specialty','appointment_date','appointment_time'];nextWorkflowFields=fallbackFields;nextFields={...fields};const activeNameKey=nextWorkflowId==='cake-order'?'customer_name':'patient_name';const lastAssistant=[...messages].reverse().find((message)=>message.from==='ai');if(!nextFields[activeNameKey]&&/^[a-z][a-z .'-]{1,40}$/i.test(text)&&(!lastAssistant||/name/i.test(lastAssistant.text)))nextFields[activeNameKey]=text.replace(/[.,]$/,'');const date=detectCalendarDate(lower);if(date)nextFields[nextWorkflowId==='cake-order'?'required_date':'appointment_date']=date;if(nextWorkflowId==='cake-order'){if(!nextFields.customer_name){reply='What is your name?';nextAction='ask_for_field'}else if(!nextFields.phone_number){reply='May I have your phone number?';nextAction='ask_for_field'}else if(!nextFields.cake_type){reply='What type of cake would you like?';nextAction='ask_for_field'}else if(!nextFields.cake_flavour){reply='Which flavour would you like?';nextAction='ask_for_field'}else if(!nextFields.cake_weight){reply='What cake weight do you need, such as 1 kg?';nextAction='ask_for_field'}else if(!nextFields.required_date){reply='What date do you need the cake?';nextAction='ask_for_field'}else if(!nextFields.delivery_method){reply='Would you like delivery or pickup?';nextAction='ask_for_field'}else{reply='What address should we use for delivery?';nextAction='ask_for_field'}}else if(!nextFields.patient_name){reply='What is your name?';nextAction='ask_for_field'}else if(!nextFields.phone_number){reply='May I have your phone number?';nextAction='ask_for_field'}else if(!nextFields.doctor_specialty){reply='Which doctor or specialty would you like to see?';nextAction='ask_for_field'}else if(!nextFields.appointment_date){reply='What date would you prefer for the appointment?';nextAction='ask_for_field'}else if(!nextFields.appointment_time){reply='What time would you prefer?';nextAction='ask_for_field'}else{reply='Would you like me to confirm this appointment?';nextAction='ask_confirmation'}nextPriority=nextFields.appointment_date==='today'||nextFields.appointment_date==='tomorrow'||nextFields.required_date==='today'||nextFields.required_date==='tomorrow'?'URGENT':'NORMAL'}
  const nextMessages=[...history,{from:'ai' as const,text:reply}];setMessages(nextMessages);setFields(nextFields);setIntent(nextIntent);setAction(nextAction);setPriority(nextPriority);setConversationId(nextConversationId);setWorkflowId(nextWorkflowId);setWorkflowFields(nextWorkflowFields);setBusy(false);if(firebaseEnabled){void saveConversation({workflowId:nextWorkflowId==='auto'?'clinic-appointment':nextWorkflowId,transcript:nextMessages,extractedFields:nextFields,priority:nextPriority,status:'in_progress'}).catch(console.error)}};
 const displayFields=workflowFields.length?workflowFields:meta.fields; const field=(name:string)=>fields[name]?<span className="filled">{String(fields[name])}</span>:<span className="missing">Missing</span>;
 return <><PageTitle eyebrow="TEST YOUR ASSISTANT" title="AI Simulator" description="Choose a workflow or let Maya/Coco detect it from the conversation." action={<div className="language-toggle"><button className="selected">English</button><button>हिन्दी</button></div>}/><div className="workflow-picker"><span><I.Workflow size={16}/> Active workflow</span><button className={workflowId==='clinic-appointment'?'selected':''} onClick={()=>reset('clinic-appointment')}><span className="workflow-mini-icon purple-mini">✦</span> Clinic appointment</button><button className={workflowId==='cake-order'?'selected':''} onClick={()=>reset('cake-order')}><span className="workflow-mini-icon orange-mini">◒</span> Cake order</button><small>{workflowId==='auto'?workflowName:workflowName}</small></div><div className="simulator-layout"><section className="panel chat-panel"><div className="chat-head"><div className="assistant-avatar"><I.Waves size={20}/></div><div><b>{workflowId==='auto'?'Maya & Coco':`${meta.assistant} · ${workflowName}`}</b><span><i className="live-dot"></i> {busy?'Thinking...':'Ready to test'}</span></div><button className="icon-btn" onClick={()=>reset(workflowId)}><I.RotateCcw size={17}/></button></div><div className="chat-messages">{messages.map((m,i)=><div className={'bubble-wrap '+m.from} key={i}><span className="bubble-label">{m.from==='ai'?(workflowId.startsWith('cake')?'Maya':'Maya'):'You'}</span><div className="bubble">{m.text}</div>{m.from==='ai'&&<small>just now</small>}</div>)}</div><div className="chat-input"><input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==='Enter'&&void send()} placeholder="Type a message to test your assistant..."/><button onClick={()=>void send()} disabled={busy}><I.ArrowUp size={18}/></button></div></section><aside className="panel inspector"><div className="panel-head"><div><h2>Live inspector</h2><p>{workflowName}</p></div><span className="live-pill"><i className="live-dot"></i> Live</span></div><InspectorRow label="Workflow" value={workflowName}/><InspectorRow label="Intent" value={intent}/><InspectorRow label="Priority" value={priority} green={priority==='NORMAL'}/><div className="inspect-section"><span>COLLECTED FIELDS</span>{displayFields.map((name)=><div className="field-row" key={name}><b>{labels[name]||name}</b>{field(name)}</div>)}</div><div className="inspect-section"><span>NEXT ACTION</span><div className="next-action"><I.MessageCircle size={16}/><b>{action.replaceAll('_',' ')}</b></div></div></aside></div></>}

function SmartSimulator(){
 const [messages,setMessages]=useState<{from:'ai'|'user';text:string}[]>([{from:'ai',text:'Hi! I’m Maya, the AI assistant for Mangalore Smile Clinic. How can I help you today?'}]);
 const [input,setInput]=useState(''); const [busy,setBusy]=useState(false); const [conversationId,setConversationId]=useState<string|undefined>();
 const [fields,setFields]=useState<Record<string,unknown>>({}); const [intent,setIntent]=useState('general_inquiry'); const [action,setAction]=useState('ask_for_field'); const [priority,setPriority]=useState<'URGENT'|'NORMAL'>('NORMAL');
 const send=async()=>{const text=input.trim();if(!text||busy)return;const userMessage={from:'user' as const,text};const history=[...messages,userMessage];setMessages(history);setInput('');setBusy(true);let reply='I can help with that. Could you share a little more detail?';let nextFields=fields;let nextIntent=intent;let nextAction=action;let nextPriority=priority;let nextConversationId=conversationId;
  try{const response=await fetch(`${import.meta.env.VITE_API_BASE_URL||'http://127.0.0.1:8000'}/api/ai/chat`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,conversation_id:conversationId,workflow_id:'clinic-appointment',language:'en',fields,history})});if(!response.ok)throw new Error('AI API request failed');const data=await response.json();reply=data.assistant_reply;nextFields=data.extracted_fields||{};nextIntent=data.intent||'general_inquiry';nextAction=data.action_required||'ask_for_field';nextConversationId=data.conversation_id;nextPriority=nextFields.preferred_date==='today'||nextFields.preferred_date==='tomorrow'?'URGENT':'NORMAL'}catch(error){console.error(error);const lower=text.toLowerCase();nextFields={...fields};const lastAssistant=[...messages].reverse().find((message)=>message.from==='ai');if(!nextFields.patient_name&&lastAssistant&&/name/i.test(lastAssistant.text)&&/^[a-z][a-z .'-]{1,40}$/i.test(text))nextFields.patient_name=text.replace(/[.,]$/,'');const date=detectCalendarDate(lower);if(date)nextFields.preferred_date=date;if(/pain|medicine|medication|diagnosis|symptom|treatment/.test(lower)){reply='I’m not able to provide medical advice or diagnose symptoms. I can help you book an appointment with a clinician. Would you like to schedule one?';nextIntent='medical_advice';nextAction='offer_booking'}else if(!nextFields.patient_name){reply='I can help you book that. What is your name?';nextIntent='book_appointment';nextAction='ask_for_field'}else if(!nextFields.preferred_date){reply='What date would you prefer for the appointment?';nextIntent='book_appointment';nextAction='ask_for_field'}else if(!nextFields.specialty){reply='Which doctor or specialty would you like to see?';nextIntent='book_appointment';nextAction='ask_for_field'}else{reply='What time works best for you?';nextIntent='book_appointment';nextAction='ask_for_field'}nextPriority=nextFields.preferred_date==='today'||nextFields.preferred_date==='tomorrow'?'URGENT':'NORMAL'}
  const nextMessages=[...history,{from:'ai' as const,text:reply}];setMessages(nextMessages);setFields(nextFields);setIntent(nextIntent);setAction(nextAction);setPriority(nextPriority);setConversationId(nextConversationId);setBusy(false);if(firebaseEnabled){void saveConversation({workflowId:'clinic-appointment',transcript:nextMessages,extractedFields:nextFields,priority:nextPriority,status:'in_progress'}).catch(console.error)}};
 const reset=()=>{setMessages([{from:'ai',text:'Hi! I’m Maya, the AI assistant for Mangalore Smile Clinic. How can I help you today?'}]);setInput('');setFields({});setIntent('general_inquiry');setAction('ask_for_field');setPriority('NORMAL');setConversationId(undefined)};
 const field=(name:string)=>fields[name]?<span className="filled">{String(fields[name])}</span>:<span className="missing">Missing</span>;
 return <><PageTitle eyebrow="TEST YOUR ASSISTANT" title="AI Simulator" description="Run a real conversation through the FastAPI assistant." action={<div className="language-toggle"><button className="selected">English</button><button>हिन्दी</button></div>}/><div className="simulator-layout"><section className="panel chat-panel"><div className="chat-head"><div className="assistant-avatar"><I.Waves size={20}/></div><div><b>Maya · Clinic Booking</b><span><i className="live-dot"></i> {busy?'Thinking...':'Ready to test'}</span></div><button className="icon-btn" onClick={reset}><I.RotateCcw size={17}/></button></div><div className="chat-messages">{messages.map((m,i)=><div className={'bubble-wrap '+m.from} key={i}><span className="bubble-label">{m.from==='ai'?'Maya':'You'}</span><div className="bubble">{m.text}</div>{m.from==='ai'&&<small>just now</small>}</div>)}</div><div className="chat-input"><input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==='Enter'&&void send()} placeholder="Type a message to test your assistant..."/><button onClick={()=>void send()} disabled={busy}><I.ArrowUp size={18}/></button></div></section><aside className="panel inspector"><div className="panel-head"><div><h2>Live inspector</h2><p>Structured conversation state</p></div><span className="live-pill"><i className="live-dot"></i> Live</span></div><InspectorRow label="Intent" value={intent}/><InspectorRow label="Priority" value={priority} green={priority==='NORMAL'}/><div className="inspect-section"><span>COLLECTED FIELDS</span><div className="field-row"><b>preferred_date</b>{field('preferred_date')}</div><div className="field-row"><b>patient_name</b>{field('patient_name')}</div><div className="field-row"><b>specialty</b>{field('specialty')}</div><div className="field-row"><b>preferred_time</b>{field('preferred_time')}</div></div><div className="inspect-section"><span>NEXT ACTION</span><div className="next-action"><I.MessageCircle size={16}/><b>{action.replaceAll('_',' ')}</b></div></div></aside></div></>}
function InspectorRow({label,value,green=false}:{label:string;value:string;green?:boolean}){return <div className="inspector-row"><span>{label}</span><b className={green?'green-text':''}>{value}</b></div>}
function liveConversationRow(record:any):Conversation{
 const data=record.collectedData||record.extractedFields||{}; const name=data.patient_name||data.customer_name||record.callerPhone||record.phoneNumber||'Unknown customer'; const initials=String(name).split(/\s+/).filter(Boolean).slice(0,2).map((part:string)=>part[0]).join('').toUpperCase()||'??'; const status=record.state==='completed'||record.status==='confirmed'?'Booked':record.status==='MISSED'?'Missed':'In progress'; const transcript=record.transcript||[]; const last=transcript.length?transcript[transcript.length-1]:null; return {id:record.id||record.conversationId,name,type:record.workflowName||record.workflowId||'AI conversation',time:record.updatedAt||record.createdAt||'just now',status,priority:record.priority==='URGENT'?'URGENT':'NORMAL',initials,color:'#eee6ff',text:record.summary||last?.content||last?.text||'Conversation captured by the AI assistant',record};
}
function Conversations({query,setQuery}:{query:string;setQuery:(s:string)=>void}){
 const profileSeed:Record<string,{phone:string;email:string;workflow:string;status:string;summary:string;notes:string;fields:Record<string,string>}>= {
  'Sarah Johnson':{phone:'+91 98765 43210',email:'sarah.johnson@email.com',workflow:'Clinic - Book Appointment',status:'In progress',summary:'New appointment request for a dentist visit tomorrow morning.',notes:'Call back to confirm the available morning slot.',fields:{patient_name:'Sarah Johnson',doctor_specialty:'Dentist',appointment_date:'Tomorrow',appointment_time:'Morning'}},
  'Rahul Mehta':{phone:'+91 98450 11223',email:'rahul.mehta@email.com',workflow:'Cake Shop - Place Cake Order',status:'Booked',summary:'Custom chocolate cake requested for Saturday.',notes:'Confirm delivery address and final price.',fields:{customer_name:'Rahul Mehta',cake_type:'Custom birthday cake',cake_flavour:'Chocolate',cake_weight:'2 kg',required_date:'Saturday',delivery_method:'Delivery'}},
  'Priya Nair':{phone:'+91 99887 77665',email:'priya.nair@email.com',workflow:'Clinic - Appointment Enquiry',status:'Contacted',summary:'Customer asked about delivery options and clinic timings.',notes:'Follow up after sending the available options.',fields:{customer_name:'Priya Nair',phone_number:'+91 99887 77665'}},
  'David Chen':{phone:'+91 90000 12345',email:'david.chen@email.com',workflow:'Clinic - Reschedule Appointment',status:'Closed',summary:'Requested to move an existing appointment to next week.',notes:'',fields:{patient_name:'David Chen',existing_date:'September 8',new_date:'September 15'}},
 };
 const [selectedName,setSelectedName]=useState('Sarah Johnson'); const [profiles,setProfiles]=useState(profileSeed); const [saved,setSaved]=useState(false); const [saveError,setSaveError]=useState(''); const [liveRecords,setLiveRecords]=useState<any[]>([]);
 const loadLive=async()=>{try{const response=await fetch(`${import.meta.env.VITE_API_BASE_URL||'http://127.0.0.1:8000'}/api/conversations`);const backendRows=response.ok?await response.json():[];const firebaseRows=firebaseEnabled?await listConversations().catch(error=>{console.error('Firebase conversation list failed:',error);return []}):[];const merged=[...backendRows,...firebaseRows.filter((firebase:any)=>!backendRows.some((backend:any)=>backend.id===firebase.id))];setLiveRecords(merged)}catch(error){console.error('Conversation list failed:',error)}};
 useEffect(()=>{void loadLive();const timer=window.setInterval(()=>void loadLive(),5000);return()=>window.clearInterval(timer)},[]);
 const liveRows=liveRecords.map(liveConversationRow); const rows=[...liveRows,...conversations.filter(c=>!liveRows.some(live=>live.name===c.name))]; const filtered=rows.filter(c=>c.name.toLowerCase().includes(query.toLowerCase())||c.type.toLowerCase().includes(query.toLowerCase())); const selected=rows.find(c=>c.name===selectedName)||rows[0];
 useEffect(()=>{if(!liveRecords.length)return;setProfiles(previous=>{const next={...previous};liveRecords.forEach(record=>{const row=liveConversationRow(record);const data=record.collectedData||record.extractedFields||{};next[row.name]={phone:data.phone_number||record.callerPhone||'',email:data.email||'',workflow:record.workflowName||record.workflowId||'AI conversation',status:row.status,summary:record.summary||row.text,notes:'',fields:Object.fromEntries(Object.entries(data).map(([key,value])=>[key,String(value??'')]))}});return next})},[liveRecords]);
 const profile=profiles[selected.name]||{phone:'',email:'',workflow:selected.type,status:selected.status,summary:selected.text,notes:'',fields:{}};
 const updateProfile=(key:string,value:string)=>{setSaved(false);setSaveError('');setProfiles(prev=>({...prev,[selected.name]:{...prev[selected.name],[key]:value}}))};
 const updateField=(key:string,value:string)=>{setSaved(false);setSaveError('');setProfiles(prev=>({...prev,[selected.name]:{...prev[selected.name],fields:{...prev[selected.name].fields,[key]:value}}}))};
 const save=async()=>{setSaved(false);setSaveError('');try{const input={customerName:selected.name,phoneNumber:profile.phone,email:profile.email,workflowName:profile.workflow,status:profile.status,summary:profile.summary,notes:profile.notes,collectedData:profile.fields};if(selected.record){const response=await fetch(`${import.meta.env.VITE_API_BASE_URL||'http://127.0.0.1:8000'}/api/conversations/${encodeURIComponent(selected.id)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(!response.ok)throw new Error('Backend could not save the live conversation')}else{if(!firebaseEnabled){setSaveError('Firebase is not configured in the running app. Restart Vite after checking frontend/.env.');return}const savedId=await updateConversation(selected.id||`demo_${selected.initials.toLowerCase()}`,input);if(!savedId)throw new Error('Firebase sign-in did not return a user. Enable Anonymous authentication.')}setSaved(true);void loadLive()}catch(error){console.error('Conversation save failed:',error);const message=error instanceof Error?error.message:String(error);setSaveError(message.includes('permission-denied')||message.includes('Missing or insufficient permissions')?'Firestore denied the write. Publish rules that allow signed-in users to write their own documents.':message)}};
 return <><PageTitle eyebrow="INBOX" title="Conversations" description="Every call, message, and follow-up in one place." action={<Button><I.Download size={16}/> Export</Button>}/><div className="toolbar"><div className="search"><I.Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search conversations"/></div><button className="filter-btn">All statuses <I.ChevronDown size={14}/></button><button className="filter-btn">All priorities <I.ChevronDown size={14}/></button></div><div className="conversation-workspace"><div className="panel conversation-list">{filtered.map(c=><button className={c.name===selected.name?'conversation-select selected':'conversation-select'} key={c.name} onClick={()=>{setSelectedName(c.name);setSaved(false);setSaveError('')}}><div className="avatar" style={{background:c.color}}>{c.initials}</div><div className="conversation-main"><b>{c.name}</b><span>{c.type}</span><small>{c.text}</small></div><div className="conversation-meta"><span className={'priority '+c.priority.toLowerCase()}>{c.priority}</span><small>{c.time}</small></div><I.ChevronRight className="row-chevron" size={16}/></button>)}</div><aside className="panel customer-detail-panel"><div className="detail-header"><div className="avatar large-avatar" style={{background:selected.color}}>{selected.initials}</div><div><h2>{selected.name}</h2><p>{profile.workflow}</p></div><span className={'priority '+selected.priority.toLowerCase()}>{selected.priority}</span></div><div className="detail-status"><span>Status</span><select value={profile.status} onChange={e=>updateProfile('status',e.target.value)}><option>In progress</option><option>Contacted</option><option>Booked</option><option>Closed</option></select></div><div className="detail-section"><span className="detail-label">CUSTOMER DETAILS</span><label>Phone number<input value={profile.phone} onChange={e=>updateProfile('phone',e.target.value)}/></label><label>Email<input value={profile.email} onChange={e=>updateProfile('email',e.target.value)}/></label></div><div className="detail-section"><span className="detail-label">COLLECTED INFORMATION</span>{Object.entries(profile.fields).map(([key,value])=><label key={key}>{key.replaceAll('_',' ')}<input value={value} onChange={e=>updateField(key,e.target.value)}/></label>)}</div><div className="detail-section"><span className="detail-label">AI SUMMARY</span><textarea value={profile.summary} onChange={e=>updateProfile('summary',e.target.value)}/><label>Internal notes<textarea value={profile.notes} onChange={e=>updateProfile('notes',e.target.value)}/></label></div><div className="detail-footer"><span className={saveError?'save-error':''}>{saveError|| (saved?'Saved to Firebase':'Unsaved changes')}</span><Button onClick={save}><I.Save size={15}/> Save details</Button></div></aside></div></>}

function LegacyConversations({query,setQuery}:{query:string;setQuery:(s:string)=>void}){const filtered=conversations.filter(c=>c.name.toLowerCase().includes(query.toLowerCase())||c.type.toLowerCase().includes(query.toLowerCase())); return <><PageTitle eyebrow="INBOX" title="Conversations" description="Every call, message, and follow-up in one place." action={<Button><I.Download size={16}/> Export</Button>}/><div className="toolbar"><div className="search"><I.Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search conversations"/></div><button className="filter-btn">All statuses <I.ChevronDown size={14}/></button><button className="filter-btn">All priorities <I.ChevronDown size={14}/></button></div><div className="panel conversation-list">{filtered.map(c=><ConversationRow c={c} key={c.name}/>)}</div></>}
