function CalendarPage(){return <><PageTitle eyebrow="SCHEDULE" title="Calendar" description="Your appointments, synced and always up to date." action={<Button><I.Plus size={17}/> New appointment</Button>}/><div className="calendar-layout"><div className="panel calendar-main"><div className="calendar-toolbar"><button className="icon-btn"><I.ChevronLeft size={18}/></button><b>September 2026</b><button className="icon-btn"><I.ChevronRight size={18}/></button><button className="filter-btn today">Today</button><span></span><button className="filter-btn">Week <I.ChevronDown size={14}/></button></div><div className="weekdays">{['MON','TUE','WED','THU','FRI','SAT','SUN'].map(x=><span key={x}>{x}</span>)}</div><div className="calendar-days">{Array.from({length:35},(_,i)=>{const day=i<7?31+i:i-6; return <div className={(day===8?'today-cell ':'')+(i<7?'muted-day':'')} key={i}><span>{day}</span>{day===8&&<div className="cal-event green-event">09:30 Sarah</div>}{day===8&&<div className="cal-event purple-event">11:00 Rahul</div>}{day===10&&<div className="cal-event orange-event">02:30 Priya</div>}</div>})}</div></div><aside className="panel day-agenda"><h2>Tuesday, Sep 8</h2><p>3 appointments scheduled</p>{[['09:30','Sarah Johnson','Dental consultation','green'],['11:00','Rahul Mehta','Follow-up visit','purple'],['02:30','Priya Nair','New patient check-in','orange']].map(a=><div className="agenda-item" key={a[0]}><b>{a[0]}</b><div className={'agenda-bar '+a[3]}><strong>{a[1]}</strong><span>{a[2]}</span></div></div>)}<div className="google-sync"><I.CalendarCheck size={17}/><span><b>Google Calendar</b><small>Connected · Last synced just now</small></span><I.CheckCircle2 size={17}/></div></aside></div></>}
function Analytics(){return <><PageTitle eyebrow="PERFORMANCE" title="Analytics" description="Understand how your assistant is impacting your business." action={<button className="filter-btn">Last 30 days <I.ChevronDown size={14}/></button>}/><div className="stats"><Stat icon={<I.PhoneCall size={19}/>} color="#dff5e9" label="Total conversations" value="246" delta="↑ 18.4%"/><Stat icon={<I.Target size={19}/>} color="#eee5ff" label="Conversion rate" value="72.8%" delta="↑ 6.2%"/><Stat icon={<I.Timer size={19}/>} color="#fff0ce" label="Avg. response time" value="1.8m" delta="↓ 24.1%"/><Stat icon={<I.HeartHandshake size={19}/>} color="#ffe4e0" label="Customer satisfaction" value="4.9/5" delta="↑ 0.3"/></div><div className="analytics-grid"><div className="panel chart-panel"><div className="panel-head"><div><h2>Conversations over time</h2><p>Daily volume across all workflows</p></div><div className="legend"><i></i> Total calls</div></div><div className="chart"><div className="y-labels"><span>40</span><span>30</span><span>20</span><span>10</span><span>0</span></div><div className="chart-area"><div className="grid-lines"></div><svg viewBox="0 0 600 210" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#6c5ce7" stopOpacity=".25"/><stop offset="1" stopColor="#6c5ce7" stopOpacity="0"/></linearGradient></defs><path d="M0,170 C45,150 55,125 95,140 S145,165 185,118 S225,130 270,108 S315,132 355,92 S395,106 430,70 S490,100 520,50 S570,65 600,28 L600,210 L0,210Z" fill="url(#area)"/><path d="M0,170 C45,150 55,125 95,140 S145,165 185,118 S225,130 270,108 S315,132 355,92 S395,106 430,70 S490,100 520,50 S570,65 600,28" fill="none" stroke="#6c5ce7" strokeWidth="3"/></svg><div className="x-labels"><span>Aug 10</span><span>Aug 17</span><span>Aug 24</span><span>Aug 31</span><span>Sep 8</span></div></div></div></div><div className="panel source-panel"><div className="panel-head"><div><h2>Top workflows</h2><p>By completed conversations</p></div></div>{[['Clinic Appointment Booking','128','72%'],['Custom Cake Order','64','48%'],['General enquiry','54','32%']].map((x,i)=><div className="source-row" key={x[0]}><div className={'source-icon s'+i}>{i+1}</div><div><b>{x[0]}</b><span>{x[1]} conversations</span></div><strong>{x[2]}</strong></div>)}</div></div></>}
